static int tinycomprsrc_forward_command(AVFilterContext *ctx, int pad_idx,
    const char *target, const char *cmd, const char *arg,
    char *res, int res_len, int flags)
{
    TinyCompressContext *s = ctx->priv;

    if (!strcmp(cmd, "map")) {
        if (!s->map || pad_idx < 0 || pad_idx >= s->nb_outputs)
            return AVERROR(EINVAL);
        s->map[pad_idx] = atoi(arg);
    } else if (!strcmp(cmd, "set_parameter"))
        compress_set_params(s->compress, arg);

--- now (after) :1184,1196 ---
    TinyCompressContext *s = ctx->priv;

    if (!strcmp(cmd, "map")) {
        /* Per-output map set by pad_idx is not supported by the MappingContext
         * module (map is managed as a string via ff_mapping_update); the
         * runtime "map" command is handled in process_command instead. */
        return AVERROR(ENOSYS);
    } else if (!strcmp(cmd, "set_parameter"))
        compress_set_params(s->compress, arg);

    return 0;
}


