               &on_event_cb, &udata, &format, &sample_rate, &channels, &codec_id) != 6)
        return AVERROR(EINVAL);

    priv->sample_fmt = format;
    priv->sample_rate = sample_rate;
    av_channel_layout_default(&priv->ch_layout, channels);
    priv->paused = false;
    priv->output_started = false;

    abufsrc_set_event_cb(ctx, on_event_cb, udata);

    ret = abufsrc_open_decoder(ctx, codec_id);
