#ifndef AVFILTER_MAPPING_H
#define AVFILTER_MAPPING_H

#include <stddef.h>
#include <stdlib.h>
#include "libavutil/error.h"
#include "libavutil/mem.h"

#define ROUTE_OFF 0
#define ROUTE_ON 1

typedef struct AVClass AVClass;

/**
 * @file
 * control routing for src filter
 */

/**
 * Parse the mapping definition.
 *
 * @param map_str      The mapping definition string.
 * @param map          Pointer to an array that will hold the parsed mapping relationships.
 *                     The array will be allocated by this function and should be freed
 *                     by the caller using av_freep().
 * @param nb_map       The number of mappings expected in the map array.
 * @return             0 on success, a negative AVERROR code on error.
 */
int avfilter_parse_mapping(const char *map_str, int **map, int nb_map);

typedef struct MappingContext MappingContext;

/**
 * Allocate mapping context
 */
MappingContext *ff_mapping_alloc(void);

/**
 * Initialize mapping context
 * @param s mapping context
 * @param nb_outputs number of outputs
 */
int ff_mapping_init(MappingContext *s, int nb_outputs);

/**
 * Free mapping context
 */
void ff_mapping_free(MappingContext **s);

/**
 * Get AVClass for AVOption support
 */
const AVClass *ff_mapping_get_class(void);

/**
 * Check if output is enabled
 * @param s mapping context
 * @param index output index
 * @return 1=enabled, 0=disabled
 */
int ff_mapping_is_enabled(MappingContext *s, int index);

