    25	/**
    26	 * Parse a mapping string and build an integer array.
    27	 *
    28	 * @param map_str    Input string to parse (must not be NULL)
    29	 * @param map        Output array pointer
    30	 * @param nb_map     Maximum number of elements to parse (must be > 0 )
    31	 * @return           0 on success, negative error code on failure
    32	 *                   - AVERROR(EINVAL): Invalid input parameters
    33	 *                   - AVERROR(ENOMEM): Memory allocation failed
    34	 *                   - AVERROR(ERANGE): Integer overflow in parsing
    35	 */
    36	int avfilter_parse_mapping(const char *map_str, int **map, int nb_map)
    37	{
    38	    int *new_map = NULL;
    39	    int new_nb_map = 0;
    40	
    41	    if (!map_str || nb_map <= 0)
    42	        return AVERROR(EINVAL);
    43	
    44	    new_map = av_calloc(nb_map, sizeof(*new_map));
    45	    if (!new_map)
    46	        return AVERROR(ENOMEM);
    47	
    48	    while (1) {
    49	        char *p;
    50	        int val = strtol(map_str, &p, 0);
    51	        if (map_str == p)
    52	            break;
    53	        map_str = p;
    54	
    55	        if (val != ROUTE_ON && val != ROUTE_OFF) {
    56	            av_freep(&new_map);
    57	            return AVERROR(ERANGE);
    58	        }
    59	
    60	        if (new_nb_map >= nb_map) {
    61	            av_freep(&new_map);
    62	            return AVERROR(EINVAL);
    63	        }
    64	
    65	        new_map[new_nb_map++] = val;
    66	    }
    67	
    68	    if (!new_nb_map) {
    69	        av_freep(&new_map);
    70	        return AVERROR(EINVAL);
    71	    }
    72	
    73	    av_freep(map);
    74	
    75	    *map = new_map;
    76	    return 0;
    77	}
