static const AVClass *abufsrc_child_class_iterate(void **iter)
{
    const AVClass *classes[] = {
        ff_mapping_get_class(),
        ff_volume_get_class(),
        NULL
    };

    uintptr_t i = (uintptr_t)*iter;
    const AVClass *c = classes[i];

    if (c)
        *iter = (void*)(i + 1);

    return c;
}

static void *abufsrc_child_next(void *obj, void *prev)
{
    BuffSrcPriv *s = obj;

    if (!prev)
        return s->mapping;
    else if (prev == s->mapping)
        return s->vol;
    else
        return NULL;
}


